const panel = document.querySelector('.xp-workshop-widget:last-child .xp-workshop-content');
if (!panel) throw Error('Controller panel unavailable');
const button = document.createElement('button');
button.textContent = 'Press A once';
button.className = 'mini-action';
const status = document.createElement('p');
status.textContent = 'Ready';
panel.append(button, status);
let active = true;
button.onclick = async () => {
  if (!active) return;
  button.disabled = true;
  try { await xlink.command('press A 100'); status.textContent = 'A pressed'; }
  catch (e) { status.textContent = 'Error: ' + e.message; }
  finally { button.disabled = false; }
};
xlink.log('Controller demo enabled');
return () => { active = false; button.onclick = null; };
